# ! [doc = " This is an implementation of a global allocator on wasm targets when"] # ! [doc = " emscripten or wasi is not in use. In that situation there's no actual runtime"] # ! [doc = " for us to lean on for allocation, so instead we provide our own!"] # ! [doc = ""] # ! [doc = " The wasm instruction set has two instructions for getting the current"] # ! [doc = " amount of memory and growing the amount of memory. These instructions are the"] # ! [doc = " foundation on which we're able to build an allocator, so we do so! Note that"] # ! [doc = " the instructions are also pretty \"global\" and this is the \"global\" allocator"] # ! [doc = " after all!"] # ! [doc = ""] # ! [doc = " The current allocator here is the `dlmalloc` crate which we've got included"] # ! [doc = " in the rust-lang/rust repository as a submodule. The crate is a port of"] # ! [doc = " dlmalloc.c from C to Rust and is basically just so we can have \"pure Rust\""] # ! [doc = " for now which is currently technically required (can't link with C yet)."] # ! [doc = ""] # ! [doc = " The crate itself provides a global allocator which on wasm has no"] # ! [doc = " synchronization as there are no threads!"] use split_decls_genesis :: ourprelude :: * ; use core :: cell :: SyncUnsafeCell ; use crate :: alloc :: { GlobalAlloc , Layout , System } ; struct SyncDlmalloc (dlmalloc :: Dlmalloc) ; unsafe impl Sync for SyncDlmalloc { } static DLMALLOC : SyncUnsafeCell < SyncDlmalloc > = SyncUnsafeCell :: new (SyncDlmalloc (dlmalloc :: Dlmalloc :: new ())) ; #[stable (feature = "alloc_system_type" , since = "1.28.0")] unsafe impl GlobalAlloc for System { #[inline] unsafe fn alloc (& self , layout : Layout) -> * mut u8 { let _lock = lock :: lock () ; unsafe { (* DLMALLOC . get ()) . 0 . malloc (layout . size () , layout . align ()) } } #[inline] unsafe fn alloc_zeroed (& self , layout : Layout) -> * mut u8 { let _lock = lock :: lock () ; unsafe { (* DLMALLOC . get ()) . 0 . calloc (layout . size () , layout . align ()) } } #[inline] unsafe fn dealloc (& self , ptr : * mut u8 , layout : Layout) { let _lock = lock :: lock () ; unsafe { (* DLMALLOC . get ()) . 0 . free (ptr , layout . size () , layout . align ()) } } #[inline] unsafe fn realloc (& self , ptr : * mut u8 , layout : Layout , new_size : usize) -> * mut u8 { let _lock = lock :: lock () ; unsafe { (* DLMALLOC . get ()) . 0 . realloc (ptr , layout . size () , layout . align () , new_size) } } } #[cfg (target_feature = "atomics")] mod lock { use crate :: sync :: atomic :: Ordering :: { Acquire , Release } ; use crate :: sync :: atomic :: { Atomic , AtomicI32 } ; static LOCKED : Atomic < i32 > = AtomicI32 :: new (0) ; pub struct DropLock ; pub fn lock () -> DropLock { loop { if LOCKED . swap (1 , Acquire) == 0 { return DropLock ; } } } impl Drop for DropLock { fn drop (& mut self) { let r = LOCKED . swap (0 , Release) ; debug_assert_eq ! (r , 1) ; } } } #[cfg (not (target_feature = "atomics"))] mod lock { #[inline] pub fn lock () { } }